from PIL import Image, ImageDraw
from pathlib import Path
import math
out=Path('projects/active/shared-proof/making-16'); out.mkdir(exist_ok=True)
W,H=900,660; paper='#EEE9DF'; ink='#22262A'; blue='#546B72'; rust='#AE624D'; pale='#D2C7B5'

def base():
 im=Image.new('RGB',(W,H),paper); return im,ImageDraw.Draw(im)
def poly(d,pts,fill): d.polygon(pts,fill=fill)
def line(d,pts,fill=ink,width=4): d.line(pts,fill=fill,width=width,joint='curve')
ims=[]
# 43 — Proof sediment: each lower band is a separate retained state, last pass makes a gap
im,d=base();
for i,(y,col,shift) in enumerate([(140,ink,0),(245,blue,24),(350,rust,-18),(455,ink,8)]):
 d.rectangle((105+shift,y,785+shift,y+52),fill=col)
 d.rectangle((150+shift,y+13,400+shift,y+20),fill=paper)
 if i==3: d.rectangle((490,y,558,y+52),fill=paper)
ims.append(im)
# 44 — Registration drift: imperfectly aligned slabs; a quiet paper bridge joins but doesn't correct
im,d=base();
for pts,col in [([(150,165),(590,128),(614,270),(166,309)],ink), ([(238,296),(705,315),(684,438),(222,420)],blue), ([(113,450),(540,428),(565,540),(126,570)],rust)]: poly(d,pts,col)
line(d,[(174,322),(730,302)],paper,5); line(d,[(187,327),(713,310)],ink,1)
ims.append(im)
# 45 — Ghost proof / reply can revise: first fine hatch, second broad incomplete plane, third interruption
im,d=base();
for x in range(180,690,22): line(d,[(x,155),(x+100,500)],pale,2)
poly(d,[(205,215),(675,170),(721,385),(244,432)],blue)
poly(d,[(440,240),(565,226),(618,391),(487,403)],paper)
line(d,[(130,495),(340,470),(420,488),(570,460),(772,480)],rust,9)
ims.append(im)
# 46 — Split matrix, asymmetry in proof order: parallel columns / movable pause
im,d=base();
for x,ys,col in [(155,[140,205,270,335,400],ink),(405,[165,230,295,360],blue),(645,[120,185,250,315,380],rust)]:
 for j,y in enumerate(ys):
  x0=x+(j%2)*16; d.rectangle((x0,y,x0+95,y+27),fill=col)
# bright aperture as missing row
ims.append(im)
# 47 — Rotating crop: one shape grows, then edge is physically changed
im,d=base();
poly(d,[(110,125),(730,170),(658,500),(152,545)],pale)
poly(d,[(235,188),(780,206),(756,380),(262,420)],blue)
poly(d,[(390,282),(900,272),(900,442),(418,468)],ink)
# white diagonal cut reveals layers
poly(d,[(645,180),(685,187),(563,500),(525,493)],paper)
line(d,[(150,555),(700,520)],rust,6)
ims.append(im)
# 48 — Two hands, reciprocal crossing paths; neither color gets total field
im,d=base();
for off in [0,18,36,54,72]:
 line(d,[(120+off,155),(350+off,255),(460+off,420),(760+off,505)],ink,3)
for off in [0,20,40,60,80]:
 line(d,[(760-off,145),(565-off,250),(430-off,400),(160-off,520)],blue,3)
# keep the meeting open with broken central segments
for x in range(385,505,17): d.rectangle((x,320,x+7,336),fill=rust)
ims.append(im)

names=['43-proof-sediment','44-registration-drift','45-ghost-and-interruption','46-three-state-interval','47-crop-revised','48-reciprocal-crossing']
for im,name in zip(ims,names): im.save(out/f'{name}.png')
# compact contact sheet
sheet=Image.new('RGB',(900,1000),'#d5d0c7')
for i,(im,name) in enumerate(zip(ims,names)):
 thumb=im.resize((420,308)); x=20+(i%2)*440; y=20+(i//2)*326
 sheet.paste(thumb,(x,y)); ImageDraw.Draw(sheet).text((x,y+308),name,fill=ink)
sheet.save(out/'contact.png')
